package com.maganimata.app;

import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;

public class GroupsActivity extends Activity {
 private final int P=Color.rgb(201,67,128),D=Color.rgb(48,39,46),M=Color.rgb(112,101,110),BG=Color.rgb(255,248,252); private String token=""; private LinearLayout list; private Handler h=new Handler(); private int currentGroup=0; private LinearLayout messages; private EditText composer; private Runnable poll;
 private int dp(float x){return(int)(x*getResources().getDisplayMetrics().density+.5f);} private TextView t(String s,float z,int c,boolean b){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setTypeface(null,b?Typeface.BOLD:Typeface.NORMAL);v.setLineSpacing(dp(1),1.03f);return v;} private GradientDrawable bg(int c,float r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}
 @Override public void onCreate(Bundle b){super.onCreate(b);token=getSharedPreferences("magani_prefs",MODE_PRIVATE).getString("auth_token","");build();loadGroups();}
 private void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(dp(10),0,dp(12),0);top.setBackgroundColor(P);TextView back=t("‹",36,Color.WHITE,false);back.setGravity(Gravity.CENTER);top.addView(back,new LinearLayout.LayoutParams(dp(48),dp(58)));TextView title=t("Community Groups",20,Color.WHITE,true);top.addView(title,new LinearLayout.LayoutParams(0,dp(58),1));root.addView(top);back.setOnClickListener(v->finish());ScrollView sc=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(dp(14),dp(14),dp(14),dp(25));sc.addView(list);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
 private void loadGroups(){Api.get("groups.php?action=list",token,new Api.Callback(){public void ok(String b){runOnUiThread(()->{try{JSONArray a=new JSONObject(b).optJSONArray("groups");list.removeAllViews();if(a==null||a.length()==0){list.addView(t("No groups yet. Check back soon.",14,M,false));return;}for(int i=0;i<a.length();i++)addGroup(a.getJSONObject(i));}catch(Exception e){showError("Could not load groups.");}});}public void err(Exception e){runOnUiThread(()->showError("Could not connect to groups."));}});}
 private void addGroup(JSONObject g){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(16),dp(15),dp(16),dp(15));card.setBackground(bg(Color.WHITE,18));TextView name=t(g.optString("name"),18,D,true);card.addView(name);TextView desc=t(g.optString("description","A safe community space for discussion."),13,M,false);desc.setPadding(0,dp(6),0,dp(8));desc.setMaxLines(3);card.addView(desc);TextView members=t(g.optInt("member_count")+" members",11,M,false);card.addView(members);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView status=t(g.optInt("joined")==1?"Joined":"Join group",13,Color.WHITE,true);status.setGravity(Gravity.CENTER);status.setBackground(bg(P,12));row.addView(status,new LinearLayout.LayoutParams(dp(125),dp(42)));card.addView(row,new LinearLayout.LayoutParams(-1,dp(50)));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,0,0,dp(12));list.addView(card,cp);int id=g.optInt("id");status.setOnClickListener(v->{if(g.optInt("joined")==1)openGroup(id,g.optString("name"));else joinGroup(id,status,g);});}
 private void joinGroup(int id,TextView btn,JSONObject g){if(token.isEmpty()){startActivity(new Intent(this,AuthActivity.class));return;}Map<String,String>m=new HashMap<>();m.put("action","join");m.put("group_id",String.valueOf(id));Api.post("groups.php",m,token,new Api.Callback(){public void ok(String b){runOnUiThread(()->openGroup(id,g.optString("name")));}public void err(Exception e){runOnUiThread(()->showError("Please login and try again."));}});}
 private void openGroup(int id,String name){currentGroup=id;LinearLayout chat=new LinearLayout(this);chat.setOrientation(LinearLayout.VERTICAL);chat.setBackgroundColor(BG);LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(dp(10),0,dp(10),0);top.setBackgroundColor(P);TextView back=t("‹",36,Color.WHITE,false);back.setGravity(Gravity.CENTER);top.addView(back,new LinearLayout.LayoutParams(dp(48),dp(58)));TextView title=t(name,18,Color.WHITE,true);top.addView(title,new LinearLayout.LayoutParams(0,dp(58),1));TextView leave=t("Leave",12,Color.WHITE,true);top.addView(leave,new LinearLayout.LayoutParams(dp(55),dp(40)));chat.addView(top);back.setOnClickListener(v->{stopPoll();build();loadGroups();});leave.setOnClickListener(v->leaveGroup());ScrollView sc=new ScrollView(this);messages=new LinearLayout(this);messages.setOrientation(LinearLayout.VERTICAL);messages.setPadding(dp(12),dp(12),dp(12),dp(12));sc.addView(messages);chat.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout bottom=new LinearLayout(this);bottom.setPadding(dp(8),dp(7),dp(8),dp(7));bottom.setBackgroundColor(Color.WHITE);composer=new EditText(this);composer.setHint("Write a message...");composer.setSingleLine(false);composer.setMaxLines(4);composer.setTextSize(14);composer.setPadding(dp(12),dp(8),dp(12),dp(8));composer.setBackground(bg(0xFFF7F1F5,18));bottom.addView(composer,new LinearLayout.LayoutParams(0,dp(48),1));TextView send=t("➤",21,P,true);send.setGravity(Gravity.CENTER);bottom.addView(send,new LinearLayout.LayoutParams(dp(54),dp(48)));chat.addView(bottom);send.setOnClickListener(v->sendMessage());setContentView(chat);loadMessages();poll=()->{if(currentGroup>0){loadMessages();h.postDelayed(poll,5000);}};h.postDelayed(poll,5000);}
 private void loadMessages(){if(currentGroup<=0)return;Api.get("groups.php?action=messages&group_id="+currentGroup,token,new Api.Callback(){public void ok(String b){runOnUiThread(()->{try{JSONArray a=new JSONObject(b).optJSONArray("messages");messages.removeAllViews();if(a==null||a.length()==0){messages.addView(t("Be the first to start the conversation.",13,M,false));return;}for(int i=0;i<a.length();i++){JSONObject x=a.getJSONObject(i);LinearLayout bubble=new LinearLayout(GroupsActivity.this);bubble.setOrientation(LinearLayout.VERTICAL);bubble.setPadding(dp(12),dp(9),dp(12),dp(9));bubble.setBackground(bg(Color.WHITE,15));TextView n=t(x.optString("name","User"),12,P,true);bubble.addView(n);bubble.addView(t(x.optString("content"),14,D,false));bubble.addView(t(x.optString("display_date"),9,M,false));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,dp(8));messages.addView(bubble,p);}messages.post(()->{ViewParent vp=messages.getParent();if(vp instanceof ScrollView)((ScrollView)vp).fullScroll(View.FOCUS_DOWN);});}catch(Exception ignored){}});}public void err(Exception e){}});}
 private void sendMessage(){String c=composer.getText().toString().trim();if(c.isEmpty())return;Map<String,String>m=new HashMap<>();m.put("action","send");m.put("group_id",String.valueOf(currentGroup));m.put("content",c);Api.post("groups.php",m,token,new Api.Callback(){public void ok(String b){runOnUiThread(()->{composer.setText("");loadMessages();});}public void err(Exception e){runOnUiThread(()->showError("Message could not be sent."));}});}
 private void leaveGroup(){new AlertDialog.Builder(this).setTitle("Leave group?").setMessage("You can join again later.").setNegativeButton("Cancel",null).setPositiveButton("Leave",(d,w)->{Map<String,String>m=new HashMap<>();m.put("action","leave");m.put("group_id",String.valueOf(currentGroup));Api.post("groups.php",m,token,new Api.Callback(){public void ok(String b){stopPoll();build();loadGroups();}public void err(Exception e){}});}).show();}
 private void stopPoll(){currentGroup=0;if(poll!=null)h.removeCallbacks(poll);}
 private void showError(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
 @Override protected void onDestroy(){stopPoll();super.onDestroy();}
}
